sealed class FakeBackend : IProfileManagerBackend {
 public int Lists,Backups,Deletes,Recoveries; public ManagedProfileEntry Last;
 public ProfileListResult Listing; public ProfileBackupResult Backup;
 public ProfileDeleteResult Delete; public Exception Error;
 public TaskCompletionSource<ProfileDeleteResult> Pending;
 public ProfileRecoveryResult Recovery=new ProfileRecoveryResult{Recovered=true,OtherProfilesPreserved=true,Message="Synthetic recovery"};
 public TaskCompletionSource<ProfileRecoveryResult> PendingRecovery;
 public Task<ProfileListResult> ListAsync(){Lists++;return Task.FromResult(Listing);}
 public Task<ProfileRestorePreview> InspectBackupAsync(string path){throw new InvalidOperationException("Restore called in legacy fixture");}
 public Task<ProfileRestoreResult> RestoreAsync(ProfileRestorePreview preview,IProgress<string> log){throw new InvalidOperationException("Restore called in legacy fixture");}
 public Task<ProfileRecoveryResult> RecoverAsync(IProgress<string> l){Recoveries++;if(PendingRecovery!=null)return PendingRecovery.Task;if(Recovery!=null&&Recovery.Recovered&&Recovery.OtherProfilesPreserved)Listing.RecoveryRequired=false;return Task.FromResult(Recovery);}
 public Task<ProfileBackupResult> BackupAsync(ManagedProfileEntry s,IProgress<string> l){Backups++;Last=s;if(Error!=null)throw Error;return Task.FromResult(Backup);}
 public Task<ProfileDeleteResult> BackupAndDeleteAsync(ManagedProfileEntry s,IProgress<string> l){Deletes++;Last=s;if(Error!=null)throw Error;return Pending==null?Task.FromResult(Delete):Pending.Task;}
}
static class ProfileUiFixture {
