 static void Receipts(){foreach(string kind in new[]{"null","id","path","verified","others","success"}){var b=Backend();if(kind=="null")b.Delete=null;else if(kind=="id")b.Delete.DeletedProfileId="1";else if(kind=="path")b.Delete.BackupPath=" ";else if(kind=="verified")b.Delete.BackupVerified=false;else if(kind=="others")b.Delete.OtherProfilesPreserved=false;using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Select(f,0);Wait(f.RunSelectedAsync(true));Check("delete receipt "+kind,b.Deletes==1&&Log(f).Contains("Confirmed selected local profile deletion:")==(kind=="success")&&b.Lists==2);if(kind=="success")Check("pending cloud is explicit",Log(f).Contains("Cloud synchronization is pending"));}}
 foreach(string kind in new[]{"null","id","path","verified"}){var b=Backend();if(kind=="null")b.Backup=null;else if(kind=="id")b.Backup.ProfileId="1";else if(kind=="path")b.Backup.BackupPath="";else b.Backup.BackupVerified=false;using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Select(f,0);Wait(f.RunSelectedAsync(false));Check("backup receipt refuses "+kind,!Log(f).Contains("Backup verified:")&&b.Lists==2&&b.Deletes==0);}}}
 static void Busy(){var b=Backend();b.Pending=new TaskCompletionSource<ProfileDeleteResult>();using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Select(f,0);Task first=f.RunSelectedAsync(true);Check("busy disables all actions",!Field<Button>(f,"refresh").Enabled&&!Field<Button>(f,"backup").Enabled&&!Field<Button>(f,"remove").Enabled&&!Field<Button>(f,"close").Enabled&&!Field<DataGridView>(f,"profiles").Enabled);Wait(f.RunSelectedAsync(true));Wait(f.RefreshProfilesAsync());Check("busy blocks reentrant operations",b.Deletes==1&&b.Lists==1);var args=new FormClosingEventArgs(CloseReason.UserClosing,false);typeof(Form).GetMethod("OnFormClosing",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{args});Check("busy blocks close",args.Cancel);b.Pending.SetResult(b.Delete);Wait(first);Check("completion refreshes and unlocks",b.Lists==2&&Field<Button>(f,"refresh").Enabled&&Field<Button>(f,"close").Enabled);}}
 static void CopyAndError(){var b=Backend();using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Select(f,0);b.Listing.Entries[0].Id="changed outside UI";b.Listing.Entries[0].ContextToken="changed";Wait(f.RunSelectedAsync(false));Check("loaded entry copied from backend DTO",b.Last.Id=="0"&&b.Last.ContextToken=="account/A;scid/B");}b=Backend();b.Error=new IOException("synthetic stale revision");using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Select(f,0);Wait(f.RunSelectedAsync(true));Check("backend stale/failure has no success claim",b.Deletes==1&&Log(f).Contains("synthetic stale revision")&&!Log(f).Contains("Confirmed selected local profile deletion:")&&b.Lists==2);}}
