 foreach(string kind in new[]{"null","not-recovered","others","success"}){b=Backend();b.Listing.RecoveryRequired=true;if(kind=="null")b.Recovery=null;else if(kind=="not-recovered")b.Recovery.Recovered=false;else if(kind=="others")b.Recovery.OtherProfilesPreserved=false;using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Wait(f.RecoverPendingAsync());Check("explicit recovery receipt "+kind,b.Recoveries==1&&b.Lists==2&&Log(f).Contains("Interrupted operation recovered:")==(kind=="success"));Check("recovery state follows fresh readonly list "+kind,Field<Button>(f,"recover").Enabled==(kind!="success"));}}
 b=Backend();b.Listing.RecoveryRequired=true;b.PendingRecovery=new TaskCompletionSource<ProfileRecoveryResult>();using(var f=new ProfileManagerForm(b,t=>DialogResult.Yes)){Wait(f.RefreshProfilesAsync());Task task=f.RecoverPendingAsync();Wait(f.RecoverPendingAsync());Wait(f.RefreshProfilesAsync());Check("recovery busy blocks all reentry",b.Recoveries==1&&b.Lists==1&&!Field<Button>(f,"recover").Enabled&&!Field<Button>(f,"close").Enabled);b.PendingRecovery.SetResult(b.Recovery);Wait(task);Check("recovery completion unlocks",Field<Button>(f,"close").Enabled&&b.Lists==2);}}
